  export default "/*\n * Copyright (c) 2023 Yookue Ltd. All rights reserved.\n *\n * Licensed under the MIT License (the \"License\")\n *\n * Permission is hereby granted, free of charge, to any person obtaining a copy\n * of this software and associated documentation files (the \"Software\"), to deal\n * in the Software without restriction, including without limitation the rights\n * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n * copies of the Software, and to permit persons to whom the Software is\n * furnished to do so, subject to the following conditions:\n *\n * The above copyright notice and this permission notice shall be included in all\n * copies or substantial portions of the Software.\n */\n\n\nimport React from 'react';\nimport {Button, Divider} from 'antd';\nimport {FireOutlined, StopOutlined} from '@ant-design/icons';\nimport {ProForm, ProFormRadio, ProFormSwitch} from '@ant-design/pro-form';\nimport {DelayModal, ConsoleUtils, type DelayModalRef} from '@yookue/ant-buddy-pro';\nimport {type ModalActionType} from '@yookue/ant-buddy-pro/field/DelayModal';\nimport {RandomUtils} from '@yookue/ts-lang-utils';\n\n\nexport default () => {\n    const delayModalRef = React.useRef<DelayModalRef>(null);\n    const [autoStart, setAutoStart] = React.useState<boolean>(true);\n    const [onceOnly, setOnceOnly] = React.useState<boolean>(true);\n    const [actionType, setActionType] = React.useState<ModalActionType>('info');\n    const [timing, setTiming] = React.useState<boolean>(autoStart);\n\n    return (\n        <>\n            <ProForm\n                name='DelayModal_demo.en-US'\n                layout='horizontal'\n                autoFocusFirstInput={false}\n                submitter={false}\n            >\n                <ProForm.Group>\n                    <ProFormSwitch\n                        label='Auto Start'\n                        checkedChildren='True'\n                        unCheckedChildren='False'\n                        fieldProps={{\n                            checked: autoStart,\n                            onChange: (value: boolean) => {\n                                setAutoStart(value);\n                                setTiming(value);\n                                if (value) {\n                                    delayModalRef.current?.startTimer();\n                                } else {\n                                    delayModalRef.current?.stopTimer();\n                                }\n                            }\n                        }}\n                    />\n                    <ProFormSwitch\n                        label='Once Only'\n                        checkedChildren='True'\n                        unCheckedChildren='False'\n                        fieldProps={{\n                            checked: onceOnly,\n                            disabled: autoStart || timing,\n                            onChange: setOnceOnly,\n                        }}\n                    />\n                </ProForm.Group>\n                <ProFormRadio.Group\n                    label='Action Type'\n                    radioType='button'\n                    fieldProps={{\n                        value: actionType,\n                        buttonStyle: 'solid',\n                        disabled: autoStart || timing,\n                        onChange: (event) => {\n                            setActionType(event.target?.value);\n                        }\n                    }}\n                    options={[\n                        {label: 'Confirm', value: 'confirm'},\n                        {label: 'Info', value: 'info'},\n                        {label: 'Warn', value: 'warn'},\n                        {label: 'Success', value: 'success'},\n                        {label: 'Error', value: 'error'},\n                        {label: 'Custom', value: 'custom'},\n                    ]}\n                />\n                <ProForm.Group>\n                    <Button\n                        icon={<FireOutlined/>}\n                        disabled={autoStart || timing}\n                        onClick={() => {\n                            delayModalRef.current?.startTimer();\n                            setTiming(true);\n                        }}\n                    >\n                        Manual Start\n                    </Button>\n                    <Button\n                        icon={<StopOutlined/>}\n                        disabled={autoStart || !timing}\n                        onClick={() => {\n                            delayModalRef.current?.stopTimer();\n                            setTiming(false);\n                        }}\n                    >\n                        Manual Stop\n                    </Button>\n                </ProForm.Group>\n            </ProForm>\n            <Divider/>\n            <span>\n                Popup a modal dialog after idle 10 seconds.\n            </span>\n            <DelayModal\n                ref={delayModalRef}\n                actionType={actionType}\n                autoStart={autoStart}\n                onceOnly={onceOnly}\n                timeout={1000 * 10}\n                modalProps={{\n                    title: 'DelayModal',\n                    children: `Oops! This is a message from modalProps. ${RandomUtils.randomString(6)}`,\n                    closable: false,\n                    maskClosable: false,\n                    okText: 'OK',\n                    cancelText: 'Cancel',\n                }}\n                modalFunProps={{\n                    title: 'DelayModal',\n                    content: `Oops! This is a message from modalFunProps. ${RandomUtils.randomString(6)}`,\n                    closable: false,\n                    maskClosable: false,\n                    okText: 'OK',\n                    cancelText: 'Cancel',\n                }}\n                onOpenChange={(open: boolean) => {\n                    ConsoleUtils.logTimestamp(false, false, 'DelayModal', 'onOpenChange open = ' + open);\n                }}\n            />\n        </>\n    );\n}\n";;
  